SET NAMES utf8mb4;

UPDATE contract_template_versions 
SET content_template = '<div style="font-family: Times New Roman, Times, serif; color: #111; line-height: 1.6;"><div style="text-align: center; margin-bottom: 24px;"><h3 style="margin: 0; text-transform: uppercase; font-size: 15px; font-weight: bold;">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</h3><p style="margin: 2px 0 0; font-size: 14px; text-decoration: underline; font-weight: bold;">Độc lập - Tự do - Hạnh phúc</p></div><h2 style="text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 20px; text-transform: uppercase;">THỎA THUẬN HỢP ĐỒNG ĐÀO TẠO & THỰC TẬP</h2><p>Căn cứ theo nhu cầu tiếp nhận thực tập và năng lực của ứng viên, hôm nay chúng tôi gồm có:</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">BÊN A: BÊN TIẾP NHẬN THỰC TẬP (CÔNG TY)</h4><p>- Đại diện: Phòng Quản Trị Nhân Sự</p><p>- Bộ phận tiếp nhận: {{contract.department}}</p><p>- Người hướng dẫn trực tiếp: {{contract.supervisor}}</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">BÊN B: THỰC TẬP SINH</h4><p>- Họ và tên: {{intern.fullName}}</p><p>- Mã định danh / CCCD: {{intern.cccd}}</p><p>- Email liên hệ: {{intern.email}}</p><p>- Số điện thoại: {{intern.phone}}</p><p>- Trường đào tạo: {{intern.university}}</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">ĐIỀU 1: VỊ TRÍ VÀ THỜI GIAN THỰC TẬP</h4><p>- Vị trí thực tập: {{contract.position}}</p><p>- Thời hạn: Từ ngày {{contract.startDate}} đến hết ngày {{contract.endDate}}.</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">ĐIỀU 2: PHỤ CẤP VÀ CHẾ ĐỘ ĐÀO TẠO</h4><p>- Mức phụ cấp hỗ trợ hàng tháng: {{contract.allowance}}</p><p>- Mức hỗ trợ trên căn cứ theo kết quả chấm công và đánh giá chuyên cần trong kỳ thực tập.</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">ĐIỀU 3: QUYỀN HẠN VÀ TRÁCH NHIỆM BẢO MẬT</h4><p>- Tuân thủ nghiêm ngặt nội quy lao động, quy chế an toàn thông tin và văn hóa doanh nghiệp của Công ty.</p><p>- Bảo mật tuyệt đối mọi thông tin kỹ thuật, mã nguồn, tài liệu dự án và bí mật kinh doanh cả trong và sau thời gian thực tập.</p><h4 style="margin: 12px 0 6px; font-weight: bold; font-size: 14px;">ĐIỀU 4: ĐIỀU KHOẢN THI HÀNH</h4><p>- Thỏa thuận riêng (nếu có): {{contract.customTerms}}</p><p>- Hai bên cam kết thực hiện đúng các nội dung đã thỏa thuận. Hợp đồng có hiệu lực kể từ ngày ký.</p><div style="margin-top: 40px; display: flex; justify-content: space-between; text-align: center;"><div style="width: 45%;"><p style="font-weight: bold; margin-bottom: 60px;">ĐẠI DIỆN BÊN A</p><p>(Ký, ghi rõ họ tên)</p></div><div style="width: 45%;"><p style="font-weight: bold; margin-bottom: 60px;">ĐẠI DIỆN BÊN B</p><p><strong>{{intern.fullName}}</strong></p></div></div></div>'
WHERE template_id = 1;
